// Playwright-like sketch
test('dataset ETL end-to-end with tenant isolation', async ({page}) => {
  const tenant = await createTenant();
  const dsId = `ds-${Date.now()}`;
  await loginAsTenantUser(tenant);
  await page.goto('/datasets');
  await page.fill('#name', dsId);
